// Count common-neighbor triples over a 15-core. All 28-graph codegrees <=3, and blue independence number at most 7. Test these directly on the induced 20-vertex partial graph with roots and common neighbors. Additionally bound core incidence by d(v)-1 via the two root codegrees.
use std::io::{self,BufRead};
fn main(){for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let mut bad=false;for i in 0..15{for j in 0..i{if(a[i]&a[j]).count_ones()>3{bad=true}}}if bad{println!("0 0");continue}let mut sets=vec![0u32];for(i,x)in a.iter().enumerate(){for j in 0..sets.len(){if sets[j]&x==0{sets.push(sets[j]|1<<i)}}}let fives:Vec<_>=sets.into_iter().filter(|x|x.count_ones()==5).collect();let s:Vec<_>=fives.iter().copied().filter(|&s|a.iter().all(|x|(s&x).count_ones()<=3)&&(0..15).all(|i|s>>i&1==0||(0..i).all(|j|s>>j&1==0||(a[i]&a[j]).count_ones()<3))).collect();let mut count=0u64;for(i,&x)in s.iter().enumerate(){for(j,&y)in s[..i].iter().enumerate(){if (x&y).count_ones()>1{continue}for &z in &s[..j]{if (x&z).count_ones()>1||(y&z).count_ones()>1{continue}if fives.iter().any(|q|q&(x|y|z)==0){continue}if (0..15).any(|i|((x>>i)&1)+((y>>i)&1)+((z>>i)&1)+1>a[i].count_ones()){continue}count+=1}}}println!("1 {}",count)}}
